using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;
public static class FixHiddenEntranceFence {public static string Main(){if(Application.isPlaying)throw new Exception("Edit Mode required");var root=GameObject.Find("New_Map/12_Farmyards_and_boundaries/Static fence cell 1_4");if(!root)throw new Exception("Fence section missing");var renderer=root.GetComponentInChildren<Renderer>(true);var collider=root.GetComponentInChildren<MeshCollider>();if(!renderer||renderer.gameObject.activeInHierarchy||!collider)throw new Exception("Unexpected fence state");System.IO.Directory.CreateDirectory("output/Trike/Backups");if(!EditorSceneManager.SaveScene(root.scene,"output/Trike/Backups/Gameplay.before-hidden-entrance-fix.unity",true))throw new Exception("Scene backup failed");Undo.RecordObject(collider,"Disable collision for hidden entrance fence");collider.enabled=false;EditorUtility.SetDirty(collider);EditorSceneManager.MarkSceneDirty(root.scene);EditorSceneManager.SaveScene(root.scene);Physics.SyncTransforms();return "Disabled only Static fence cell 1_4/Combined static collision; its Combined On visual is already inactive. Scene saved.";}}

